Rewrite the following GNU C++14 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to rewrite:
<original_code>
#include <bits/stdc++.h>
#define inf 17446744073709551616ull
#define ll unsigned long long
using namespace std;
ll mod,n,k,dp[18][250005];
ll fac[250005],inv[250005];
inline ll qpow(ll a,ll b)
{ll res=1ll,tp=a;
while (b)
{if (b&1ll) {res*=tp;res%=mod;}
tp*=tp;tp%=mod;b>>=1ll;
}
return res;
}
inline ll cal(int a,int b)
{return (((fac[a]*inv[b])%mod)*inv[a-b])%mod;}
inline ll calc()
{int i,j,l;fac[0]=1ll;
for (i=1;i<=n;i++) fac[i]=fac[i-1]*((ll)(i))%mod;
inv[n]=qpow(fac[n],mod-2ll);
for (i=n-1;i>=0;i--) inv[i]=inv[i+1]*((ll)(i+1))%mod;
for (i=1;i<=n;i++) dp[1][i]=inv[i];
ll ans=dp[1][n]*cal(k,1)%mod;
int t=min(17,((int)(k)));
for (i=2;i<=t;i++)
{for (j=n;j;j=(j-1)&n)
{if (!dp[i-1][j]) {continue;}
int r=n^j;
for (l=r;l;l=(l-1)&r)
{dp[i][j+l]+=dp[i-1][j]*inv[l];
if (dp[i][j+l]>inf) dp[i][j+l]%=mod;
}
}
for (j=n;j;j=(j-1)&n) dp[i][j]%=mod;
ans+=dp[i][n]*cal(k,i);ans%=mod;
}
ans*=fac[n];ans%=mod;
return ans;
}
int main (){
	cin>>n>>k>>mod;
	ll ans=qpow(k,n);
	if (n%2==0) ans=(ans-calc()+mod)%mod;
	cout<<ans<<endl;
	return 0;
}
</original_code>
